SCANNER_LOCK=pathlib.Path('runtime_state/oracle/final_boss_dual/scanner.lock')
EXTERNAL_EXECUTION_AUTHORITY=False
SIGNING=False
BROADCAST=False
REPORT=pathlib.Path('runtime_state/oracle/final_boss_dual/oracle_387_variable_size_install.json')

class Hold(RuntimeError):pass

def normalized(raw):return raw.replace(b'\r\n',b'\n')
def sha(raw):return hashlib.sha256(normalized(raw)).hexdigest()
def payload_assets():
    items=json.loads(zlib.decompress(base64.b85decode(PAYLOAD.encode())).decode('utf-8'))
    if set(items)!=set(MANIFEST):raise Hold('ASSET_MANIFEST_SET_MISMATCH')
    for p,t in items.items():
        if not isinstance(t,str) or sha(t.encode('utf-8'))!=MANIFEST[p]['after']:
            raise Hold('EMBEDDED_SOURCE_HASH_MISMATCH')
    return items

def audit_source():
    items=payload_assets()
    scanner=items['qseries_v2/oracle_execution/solana_atomic_executor/boss_scanner_live.py']
    if 'Q20_BEST_PER_DIRECTION' not in scanner or 'CANARY' in scanner or 'size_lamports' not in scanner:
        raise Hold('SCANNER_VARIABLE_SIZE_SOURCE_INVALID')
    source=items['qseries_v2/oracle_execution/solana_atomic_executor/oracle_378_native_reverse_atomic.py']
    if "quote_reverse_only(self.old,snap,size)" not in source or "wsol_before<size" not in source:
        raise Hold('REVERSE_VARIABLE_SIZE_SOURCE_INVALID')
    if 'REVERSE_SIZE_NOT_010' in source or 'REVERSE_010_ONLY_UNTIL_CERTIFIED' in source:
        raise Hold('FIXED_SIZE_REVERSE_GUARD_STILL_ACTIVE')
    js=items['qseries_v2/oracle_execution/solana_atomic_executor/oracle_376_native_sdk/oracle_378_sdk_reverse_unsigned.mjs']
    if 'REVERSE_SIZE_NOT_SAFE_POSITIVE' not in js or 'REVERSE_SIZE_NOT_010' in js:
        raise Hold('REVERSE_NODE_SIZE_GUARD_INVALID')
    if any((EXTERNAL_EXECUTION_AUTHORITY,SIGNING,BROADCAST)):
        raise Hold('EXECUTION_AUTHORITY_VIOLATION')
    for p,t in items.items():
        if p.endswith('.py'):compile(t,p,'exec')
    print('[ORACLE387_SOURCE_AUDIT_PASS] complete_source_assets=%d scanner_size=Q20_OPTIMAL_PER_DIRECTION unsigned_only=True'%len(items),flush=True)

def installation_plan():
    items=payload_assets()
    replacements=[];already=[]
    for relative,content in items.items():
        p=pathlib.Path(relative)
        if not p.is_file():raise Hold('EXPECTED_PREEXISTING_SOURCE_MISSING:'+relative)
        now=sha(p.read_bytes());baseline=MANIFEST[relative]
        if now==baseline['after']:
            already.append(relative);continue
        if now!=baseline['before']:
            raise Hold('SOURCE_CHANGED_REFUSE_OVERWRITE:'+relative)
        replacements.append((p,content))
    return replacements,already

def install():
    audit_source()
    # Never replace a module in a running scanner's source tree.
    if SCANNER_LOCK.exists():raise Hold('STOP_SCANNER_BEFORE_ORACLE387_INSTALL_NO_LOCK_DELETION')
    replacements,already=installation_plan()  # preflight ALL byte fingerprints before ANY changes
    if not replacements:
        print('[ORACLE387_ALREADY_INSTALLED] files=%d'%len(already),flush=True);return
    written=[]
    try:
        for path,data in replacements:
            fd,tmp=tempfile.mkstemp(prefix='.oracle387.',dir=str(path.parent))
            with os.fdopen(fd,'wb') as f:f.write(data.encode('utf-8'))
            if path.suffix=='.py':compile(data,str(path),'exec')
            written.append((path,pathlib.Path(tmp)))
        for p,tmp in written:os.replace(tmp,p)
    finally:
        for _,tmp in written:
            if tmp.exists():tmp.unlink()
    verify()
    rep={'build':'ORACLE387','replaced_full_source_files':len(replacements),
         'already_current':len(already),'files':[str(x[0]) for x in replacements],
         'scanner_322_frozen_q18_q20_q25':True,'sqlite_bus_schema_unchanged':True,
         'size_source':'Q20_FULL_SIZE_CURVE_BEST_PER_DIRECTION',
         'executor_repricing':'EXACT_SCANNER_SIZE','execution_authority':False,
         'signing':False,'broadcast':False,'private_key_used':False}
    REPORT.parent.mkdir(parents=True,exist_ok=True)
    REPORT.write_text(json.dumps(rep,indent=2,sort_keys=True)+'\n',encoding='utf-8')
    print('[ORACLE387_INSTALL_PASS]',json.dumps({'replaced':len(replacements),'already':len(already),'dynamic':True,'scanner_stopped':True},sort_keys=True),flush=True)

def verify():
    for relative,entry in MANIFEST.items():
        p=pathlib.Path(relative)
        if not p.is_file() or sha(p.read_bytes())!=entry['after']:
            raise Hold('INSTALLED_SOURCE_HASH_MISMATCH:'+relative)
    assert not any((EXTERNAL_EXECUTION_AUTHORITY,SIGNING,BROADCAST))
    print('[ORACLE387_BYTE_VERIFIED] complete_source_files=%d'%len(MANIFEST),flush=True)

def node_check():
    path=pathlib.Path('qseries_v2/oracle_execution/solana_atomic_executor/oracle_376_native_sdk/oracle_378_sdk_reverse_unsigned.mjs')
    p=subprocess.run(['node','--check',str(path)],capture_output=True,text=True,timeout=20)
    if p.returncode:
        raise Hold('ORACLE387_NODE_SYNTAX_FAIL')
    print('[ORACLE387_NODE_CHECK_PASS] size=VARIABLE_UNSIGNED',flush=True)

def scanner_audit():
    verify()
    # Normal scanner launcher performs its OWN frozen Q25/Q20/Q18 hash checks.
    p=subprocess.run([sys.executable,'build_oracle_322_scanner_isolated_discovery.py','--audit'],timeout=60)
    if p.returncode:raise Hold('ORACLE322_FROZEN_AUDIT_FAILED')
    print('[ORACLE387_SCANNER_AUDIT_PASS] original_Q25_Q20_Q18_hashes_unchanged',flush=True)

def tests():
    items=payload_assets();scanner=items['qseries_v2/oracle_execution/solana_atomic_executor/boss_scanner_live.py']
    class T(unittest.TestCase):
        def test_source_manifest(self):self.assertEqual(len(items),11)
        def test_scanner_not_fixed(self):self.assertNotIn('CANARY',scanner)
        def test_scanner_curve(self):self.assertIn('q20.FAST_SIZES=tuple(q20.FULL_SIZE_CURVE)',scanner)
        def test_scanner_selected_size(self):self.assertIn('size=int(op[\'start\'])',scanner)
        def test_directions(self):
            self.assertIn("'PUMP_TO_METEORA','METEORA_TO_PUMP'",scanner)
        def test_after_complete_quote(self):
            self.assertLess(scanner.index('value=original[7](self,token,row)'),scanner.index('candidates=choose_direction_best(tls.quote_rows)'))
        def test_bus_columns(self):
            self.assertIn('size_lamports INTEGER NOT NULL',scanner)
        def test_dedupe(self):self.assertIn('self.newer_waiting(token,int(tls.row_generation))',scanner)
        def test_source_admission(self):
            x=items['build_oracle_368_source_boundary_repair.py']
            self.assertIn("1 <= candidate['size_lamports'] <= 9007199254740991",x)
        def test_ingress_admission(self):
            x=items['build_oracle_363_scanner_bus_binding_replacement.py']
            self.assertIn('MIN_SIZE = 1',x);self.assertIn('MAX_SIZE = 9007199254740991',x)
        def test_reverse_native_size(self):
            x=items['build_oracle_378_native_profit_path_visibility.py']
            self.assertIn("'size_lamports':size",x)
            self.assertNotIn('REVERSE_010_ONLY_UNTIL_CERTIFIED',x)
        def test_reverse_js(self):
            x=items['qseries_v2/oracle_execution/solana_atomic_executor/oracle_376_native_sdk/oracle_378_sdk_reverse_unsigned.mjs']
            self.assertIn('Number.isSafeInteger(x.size_lamports)',x)
        def test_pool_router(self):
            x=items['build_oracle_384_exact_pool_free_rpc_repair.py']
            self.assertNotIn('size!=EXPECTED_CANARY',x)
        def test_wallet_balance_guard(self):
            x=items['build_oracle_378_native_profit_path_visibility.py']
            self.assertIn('if wsol_before<size:',x)
        def test_partial_size_isolation(self):self.assertIn("str(exc)=='DLMM_PARTIAL'",scanner)
        def test_full_fill_guard(self):
            x=items['build_oracle_378_native_profit_path_visibility.py']
            self.assertIn('DLMM_PARTIAL_FILL_REJECT',x)
        def test_no_sign(self):
            self.assertEqual((EXTERNAL_EXECUTION_AUTHORITY,SIGNING,BROADCAST),(False,False,False))
        def test_positive_size_validation(self):
            self.assertIn("if type(size) is not int or size<=0",scanner)
        def test_all_source_python_compiles(self):
            for p,t in items.items():
                if p.endswith('.py'):compile(t,p,'exec')
        def test_baseline_manifest_digests(self):
            for k,entry in MANIFEST.items():self.assertEqual(len(entry['before']),64)
    result=unittest.TextTestRunner(verbosity=1).run(unittest.defaultTestLoader.loadTestsFromTestCase(T))
    print('[ORACLE387_TEST_PASS]' if result.wasSuccessful() else '[ORACLE387_TEST_FAIL]',result.testsRun,flush=True)
    return 0 if result.wasSuccessful() else 1

def main():
    a=argparse.ArgumentParser()
    m=a.add_mutually_exclusive_group(required=True)
    for flag in ('install','test','audit','verify','node-check','scanner-audit'):m.add_argument('--'+flag,action='store_true')
    o=a.parse_args()
    if o.install:install();return 0
    if o.test:return tests()
    if o.audit:audit_source();return 0
    if o.verify:verify();return 0
    if o.node_check:node_check();return 0
    if o.scanner_audit:scanner_audit();return 0
    return 2
if __name__=='__main__':raise SystemExit(main())
